"""Loading CSV files into simple in-memory tables."""

import csv
import os
import re
from dataclasses import dataclass
from typing import Any, List

from .errors import QueryError


_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


@dataclass
class Table:
    """A CSV table: a header row and converted data rows."""

    header: List[str]
    rows: List[List[Any]]

    def index(self, name: str) -> int:
        """Return the position of ``name`` in the header, ignoring case.

        A missing or ambiguous (duplicate) column name is a query error.
        """
        lowered = name.lower()
        matches = [i for i, heading in enumerate(self.header) if heading.lower() == lowered]
        if not matches:
            raise QueryError("unknown column: %s" % name)
        if len(matches) > 1:
            raise QueryError("ambiguous column: %s" % name)
        return matches[0]


def _convert(field: str) -> Any:
    """Convert one CSV field to NULL, an int, a float, or a string."""
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory: str, name: str) -> Table:
    """Read ``<directory>/<name>.csv`` and return a :class:`Table`."""
    path = os.path.join(directory, name + ".csv")
    try:
        handle = open(path, newline="", encoding="utf-8")
    except OSError as exc:
        raise QueryError("cannot read table %s: %s" % (name, exc)) from exc

    with handle:
        reader = csv.reader(handle)
        header = None
        rows = []
        try:
            for record in reader:
                if not record:
                    # Blank line: csv.reader yields an empty record.
                    continue
                if header is None:
                    header = record
                    continue
                if len(record) != len(header):
                    raise QueryError(
                        "row %d in table %s has %d fields, expected %d"
                        % (reader.line_num, name, len(record), len(header))
                    )
                rows.append([_convert(field) for field in record])
        except csv.Error as exc:
            raise QueryError("cannot parse table %s: %s" % (name, exc)) from exc
        except UnicodeDecodeError as exc:
            raise QueryError("cannot decode table %s: %s" % (name, exc)) from exc

    if header is None:
        raise QueryError("table %s has no header row" % name)
    return Table(header=header, rows=rows)

"""Execution of parsed minisql queries against CSV tables."""

import functools
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Sequence, Tuple

from . import ast, values
from .errors import QueryError
from .result import Result
from .table import Table, load_table


# Normalised aggregate names.  ``values.AGGREGATES`` may be a set or a dict.
_AGGREGATES = frozenset(str(name).upper() for name in values.AGGREGATES)


@dataclass
class _Output:
    """One output column: either a table column or a computed expression."""

    name: str
    index: Optional[int] = None
    expr: Optional[ast.Expr] = None


@dataclass
class _OrderItem:
    """A resolved ORDER BY item: an output position or an expression."""

    desc: bool
    index: Optional[int] = None
    expr: Optional[ast.Expr] = None


@dataclass
class _Plan:
    outputs: List[_Output]
    names: List[str]
    order: List[_OrderItem]
    grouped: bool


def execute(query: ast.Query, directory: str) -> Result:
    """Execute ``query`` against the CSV files in ``directory``."""
    try:
        table = load_table(directory, query.table)
        plan = _build_plan(query, table)
        entries = _evaluate(query, table, plan)
        return Result(plan.names, [tuple(row) for row, _source in entries])
    except QueryError:
        raise
    except Exception as exc:  # keep the public error contract
        message = str(exc) or exc.__class__.__name__
        raise QueryError(message) from exc


# ---------------------------------------------------------------------------
# Planning and static validation


def _star_used(query: ast.Query) -> bool:
    if query.star:
        return True
    return any(isinstance(item.expr, ast.Star) for item in query.columns)


def _build_outputs(query: ast.Query, table: Table) -> List[_Output]:
    """Expand the select list and work out the output column names."""
    outputs = []

    def add_star() -> None:
        for index, heading in enumerate(table.header):
            outputs.append(_Output(name=heading, index=index))

    if query.star:
        add_star()
        return outputs

    for item in query.columns:
        expr = item.expr
        if isinstance(expr, ast.Star):
            add_star()
            continue
        if isinstance(expr, ast.Column):
            index = table.index(expr.name)
            name = item.alias if item.alias is not None else table.header[index]
            outputs.append(_Output(name=name, index=index))
        else:
            name = item.alias if item.alias is not None else expr.text
            outputs.append(_Output(name=name, expr=expr))
    return outputs


def _validate_expr(
    expr: ast.Expr,
    table: Table,
    context: str,
    inside_aggregate: bool,
    aggregates: List[str],
) -> None:
    """Validate columns and functions, collecting aggregate uses."""
    if isinstance(expr, ast.Literal):
        return
    if isinstance(expr, ast.Column):
        table.index(expr.name)
        return
    if isinstance(expr, ast.Star):
        raise QueryError("'*' is only allowed in SELECT * or COUNT(*)")
    if isinstance(expr, ast.Func):
        name = expr.name.upper()
        if expr.star:
            if name != "COUNT":
                raise QueryError("'*' is only allowed in COUNT(*)")
            if expr.args and not (
                len(expr.args) == 1 and isinstance(expr.args[0], ast.Star)
            ):
                raise QueryError("COUNT(*) does not take arguments")
            if context == "where":
                raise QueryError("aggregate functions are not allowed in WHERE")
            if context == "group_by":
                raise QueryError("aggregate functions are not allowed in GROUP BY")
            if inside_aggregate:
                raise QueryError("aggregate functions cannot be nested")
            aggregates.append(name)
            return
        if name in _AGGREGATES:
            if context == "where":
                raise QueryError("aggregate functions are not allowed in WHERE")
            if context == "group_by":
                raise QueryError("aggregate functions are not allowed in GROUP BY")
            if inside_aggregate:
                raise QueryError("aggregate functions cannot be nested")
            if len(expr.args) != 1:
                raise QueryError("wrong number of arguments to %s()" % name)
            aggregates.append(name)
            _validate_expr(expr.args[0], table, context, True, aggregates)
            return

        # A scalar function.
        values.check_call(name, len(expr.args))
        for arg in expr.args:
            _validate_expr(arg, table, context, inside_aggregate, aggregates)
        return

    for child in ast.children(expr):
        _validate_expr(child, table, context, inside_aggregate, aggregates)


def _check_grouped_expr(
    expr: ast.Expr,
    group_signatures: set,
    group_columns: set,
) -> None:
    """Check that a non-aggregate expression is allowed by GROUP BY."""
    if ast.signature(expr) in group_signatures:
        return
    if isinstance(expr, ast.Func) and expr.name.upper() in _AGGREGATES:
        # Column references inside aggregate arguments are exempt.
        return
    if isinstance(expr, ast.Column):
        if expr.name.lower() not in group_columns:
            raise QueryError(
                "column %r must appear in GROUP BY or be used in an aggregate"
                % expr.name
            )
        return
    if isinstance(expr, ast.Star):
        raise QueryError("'*' is not allowed in a grouped query")
    for child in ast.children(expr):
        _check_grouped_expr(child, group_signatures, group_columns)


def _resolve_order(
    query: ast.Query, table: Table, names: Sequence[str]
) -> List[_OrderItem]:
    """Resolve ORDER BY items to output positions or input expressions."""
    order = []
    for item in query.order_by:
        expr = item.expr
        if (
            isinstance(expr, ast.Literal)
            and isinstance(expr.value, int)
            and not isinstance(expr.value, bool)
        ):
            position = expr.value
            if position < 1 or position > len(names):
                raise QueryError("ORDER BY position %d is out of range" % position)
            order.append(_OrderItem(desc=item.desc, index=position - 1))
            continue

        if isinstance(expr, ast.Column):
            lowered = expr.name.lower()
            for index, name in enumerate(names):
                if name.lower() == lowered:
                    order.append(_OrderItem(desc=item.desc, index=index))
                    break
            else:
                order.append(_OrderItem(desc=item.desc, expr=expr))
            continue

        order.append(_OrderItem(desc=item.desc, expr=expr))
    return order


def _build_plan(query: ast.Query, table: Table) -> _Plan:
    outputs = _build_outputs(query, table)
    names = [output.name for output in outputs]

    select_aggregates: List[str] = []
    if not query.star:
        for item in query.columns:
            if not isinstance(item.expr, ast.Star):
                _validate_expr(item.expr, table, "select", False, select_aggregates)

    if query.where is not None:
        _validate_expr(query.where, table, "where", False, [])

    for expr in query.group_by:
        _validate_expr(expr, table, "group_by", False, [])

    having_aggregates: List[str] = []
    if query.having is not None:
        _validate_expr(query.having, table, "having", False, having_aggregates)

    order = _resolve_order(query, table, names)
    order_aggregates: List[str] = []
    for item in order:
        if item.expr is not None:
            _validate_expr(item.expr, table, "order_by", False, order_aggregates)

    grouped = bool(
        query.group_by
        or select_aggregates
        or having_aggregates
        or order_aggregates
    )

    if grouped:
        group_signatures = {ast.signature(expr) for expr in query.group_by}
        group_columns = {
            expr.name.lower()
            for expr in query.group_by
            if isinstance(expr, ast.Column)
        }

        if _star_used(query):
            for heading in table.header:
                if heading.lower() not in group_columns:
                    raise QueryError(
                        "SELECT * is not allowed in a grouped query unless every "
                        "column is a GROUP BY column"
                    )

        if not query.star:
            for item in query.columns:
                if not isinstance(item.expr, ast.Star):
                    _check_grouped_expr(item.expr, group_signatures, group_columns)

        if query.having is not None:
            _check_grouped_expr(query.having, group_signatures, group_columns)

        for item in order:
            if item.expr is not None:
                _check_grouped_expr(item.expr, group_signatures, group_columns)

    return _Plan(outputs=outputs, names=names, order=order, grouped=grouped)


# ---------------------------------------------------------------------------
# Evaluation


def _eval(
    expr: ast.Expr,
    table: Table,
    row: Optional[List[Any]],
    group: Optional[List[List[Any]]],
) -> Any:
    """Evaluate an expression for one row and, when grouped, one group."""
    if isinstance(expr, ast.Literal):
        return expr.value
    if isinstance(expr, ast.Column):
        if row is None:
            raise QueryError("column %r cannot be evaluated here" % expr.name)
        return row[table.index(expr.name)]
    if isinstance(expr, ast.Star):
        raise QueryError("'*' is only allowed in COUNT(*)")
    if isinstance(expr, ast.Unary):
        operand = _eval(expr.operand, table, row, group)
        if expr.op == "-":
            return values.sql_negate(operand)
        if expr.op.upper() == "NOT":
            return values.sql_not(operand)
        raise QueryError("unknown unary operator: %s" % expr.op)
    if isinstance(expr, ast.Not):
        return values.sql_not(_eval(expr.operand, table, row, group))
    if isinstance(expr, ast.Binary):
        op = expr.op
        upper = op.upper()
        if upper == "AND":
            return values.sql_and(
                _eval(expr.left, table, row, group),
                _eval(expr.right, table, row, group),
            )
        if upper == "OR":
            return values.sql_or(
                _eval(expr.left, table, row, group),
                _eval(expr.right, table, row, group),
            )

        left = _eval(expr.left, table, row, group)
        right = _eval(expr.right, table, row, group)
        if op in ("+", "-", "*", "/"):
            return values.sql_arithmetic(op, left, right)
        if op == "||":
            return values.sql_concat(left, right)
        if upper in ("=", "!=", "<>", "<", "<=", ">", ">="):
            comparator = "!=" if upper == "<>" else upper
            return values.sql_compare(comparator, left, right)
        raise QueryError("unknown operator: %s" % op)
    if isinstance(expr, ast.IsNull):
        return values.sql_is_null(
            _eval(expr.operand, table, row, group), expr.negated
        )
    if isinstance(expr, ast.InList):
        value = _eval(expr.operand, table, row, group)
        items = [_eval(item, table, row, group) for item in expr.items]
        return values.sql_in(value, items, expr.negated)
    if isinstance(expr, ast.Between):
        value = _eval(expr.operand, table, row, group)
        low = _eval(expr.low, table, row, group)
        high = _eval(expr.high, table, row, group)
        return values.sql_between(value, low, high, expr.negated)
    if isinstance(expr, ast.Like):
        value = _eval(expr.operand, table, row, group)
        pattern = _eval(expr.pattern, table, row, group)
        return values.sql_like(value, pattern, expr.negated)
    if isinstance(expr, ast.Func):
        name = expr.name.upper()
        if name in _AGGREGATES:
            if group is None:
                raise QueryError(
                    "aggregate function %s() used outside a grouped query" % name
                )
            if expr.star:
                return values.count_star(len(group))
            if len(expr.args) != 1:
                raise QueryError("wrong number of arguments to %s()" % name)
            argument = expr.args[0]
            argument_values = [
                _eval(argument, table, member, None) for member in group
            ]
            return values.aggregate(name, argument_values)
        if name == "COALESCE":
            # Lazy: later arguments are not evaluated once a value is found.
            for arg in expr.args:
                value = _eval(arg, table, row, group)
                if value is not None:
                    return value
            return None
        arguments = [_eval(arg, table, row, group) for arg in expr.args]
        return values.call_scalar(name, arguments)

    raise QueryError("unknown expression node: %s" % type(expr).__name__)


def _project(
    outputs: Sequence[_Output],
    table: Table,
    row: Optional[List[Any]],
    group: Optional[List[List[Any]]],
) -> Tuple[Any, ...]:
    projected = []
    for output in outputs:
        if output.index is not None:
            if row is None:
                raise QueryError(
                    "column %r cannot be evaluated without a row" % output.name
                )
            projected.append(row[output.index])
        else:
            projected.append(_eval(output.expr, table, row, group))
    return tuple(projected)


def _eval_order(
    expr: ast.Expr,
    table: Table,
    source: Any,
    grouped: bool,
) -> Any:
    if grouped:
        group = source
        row = group[0] if group else None
        return _eval(expr, table, row, group)
    return _eval(expr, table, source, None)


def _compare_sort_values(left: Any, right: Any, desc: bool) -> int:
    if left is None and right is None:
        return 0
    if left is None:
        return 1 if desc else -1
    if right is None:
        return -1 if desc else 1
    comparison = values.sort_compare(left, right)
    if comparison < 0:
        comparison = -1
    elif comparison > 0:
        comparison = 1
    return -comparison if desc else comparison


def _evaluate(
    query: ast.Query, table: Table, plan: _Plan
) -> List[Tuple[Tuple[Any, ...], Any]]:
    """Run the query and return ``(output_values, source)`` pairs."""
    rows = list(table.rows)
    if query.where is not None:
        rows = [
            row
            for row in rows
            if _eval(query.where, table, row, None) is True
        ]

    entries: List[Tuple[Tuple[Any, ...], Any]] = []

    if plan.grouped:
        if query.group_by:
            groups: Dict[Any, List[List[Any]]] = {}
            for row in rows:
                key = values.group_key(
                    tuple(
                        _eval(expr, table, row, None) for expr in query.group_by
                    )
                )
                groups.setdefault(key, []).append(row)
            group_rows = list(groups.values())
        else:
            # Without GROUP BY all remaining rows form one group.
            group_rows = [rows]

        for group in group_rows:
            row = group[0] if group else None
            if query.having is not None:
                if _eval(query.having, table, row, group) is not True:
                    continue
            entries.append((_project(plan.outputs, table, row, group), group))
    else:
        if query.having is not None:
            rows = [
                row
                for row in rows
                if _eval(query.having, table, row, None) is True
            ]
        for row in rows:
            entries.append((_project(plan.outputs, table, row, None), row))

    if query.distinct:
        seen = set()
        unique = []
        for projection, source in entries:
            key = values.distinct_key(projection)
            if key in seen:
                continue
            seen.add(key)
            unique.append((projection, source))
        entries = unique

    if plan.order:
        decorated = []
        for projection, source in entries:
            keys = []
            for item in plan.order:
                if item.index is not None:
                    keys.append(projection[item.index])
                else:
                    keys.append(
                        _eval_order(item.expr, table, source, plan.grouped)
                    )
            decorated.append((keys, projection, source))

        descs = [item.desc for item in plan.order]

        def compare(first: Any, second: Any) -> int:
            for position, desc in enumerate(descs):
                result = _compare_sort_values(
                    first[0][position], second[0][position], desc
                )
                if result:
                    return result
            return 0

        decorated.sort(key=functools.cmp_to_key(compare))
        entries = [
            (projection, source)
            for _keys, projection, source in decorated
        ]

    if query.offset is not None:
        entries = entries[query.offset :]
    if query.limit is not None:
        entries = entries[: query.limit]

    return entries
